var currentTime = new Date();
var desiredHydrationLevel = 0.8; // 80% hydration level

// Define the penalty for not drinking enough water before dawn
var penalty = 0.1; // 10% penalty for not drinking enough water before dawn

// Define the reminder message for not drinking enough water before dawn
var reminderMessage = "You're not drinking enough water! Bloating is coming...";

// Define the hydration level threshold for the penalty
var threshold = 0.7; // 70% hydration level threshold

// Define the user's hydration level
